-- Original and Touchline views, including the corrected player totals. Run after data.

USE touchline_clean_20261124;

SET NAMES utf8mb4;

CREATE SQL SECURITY INVOKER VIEW `tl_seasons` AS select `s`.`season_id` AS `season_id`,`s`.`competition_id` AS `competition_id`,`s`.`season_label` AS `season_label`,`s`.`start_date` AS `start_date`,`s`.`end_date` AS `end_date` from (`seasons` `s` join `competitions` `c` on((`s`.`competition_id` = `c`.`competition_id`))) where ((`c`.`competition_name` = 'Premier League') and (`s`.`season_label` = '2023/24'));

CREATE SQL SECURITY INVOKER VIEW `v_above_any_team_goal_total` AS select `p`.`player_id` AS `player_id`,`p`.`full_name` AS `full_name`,`t`.`team_name` AS `team_name`,sum(`s`.`goals`) AS `recorded_goals` from ((`players` `p` join `teams` `t` on((`t`.`team_id` = `p`.`team_id`))) join `player_match_stats` `s` on((`s`.`player_id` = `p`.`player_id`))) group by `p`.`player_id`,`p`.`full_name`,`t`.`team_name` having sum(`s`.`goals`) > any (select sum(`s2`.`goals`) from (`players` `p2` join `player_match_stats` `s2` on((`s2`.`player_id` = `p2`.`player_id`))) group by `p2`.`team_id`);

CREATE SQL SECURITY INVOKER VIEW `v_goal_or_assist_players` AS select `p`.`player_id` AS `player_id`,`p`.`full_name` AS `full_name`,`t`.`team_name` AS `team_name` from (`players` `p` join `teams` `t` on((`t`.`team_id` = `p`.`team_id`))) where `p`.`player_id` in (select `player_match_stats`.`player_id` from `player_match_stats` where (`player_match_stats`.`goals` > 0) union select `player_match_stats`.`player_id` from `player_match_stats` where (`player_match_stats`.`assists` > 0));

CREATE SQL SECURITY INVOKER VIEW `v_league_standings` AS select row_number() OVER (PARTITION BY `x`.`season_id` ORDER BY `x`.`points` desc,`x`.`goal_difference` desc,`x`.`goals_for` desc,`x`.`team_name` )  AS `league_position`,`x`.`season_id` AS `season_id`,`x`.`season_label` AS `season_label`,`x`.`team_id` AS `team_id`,`x`.`team_name` AS `team_name`,`x`.`played` AS `played`,`x`.`wins` AS `wins`,`x`.`draws` AS `draws`,`x`.`losses` AS `losses`,`x`.`goals_for` AS `goals_for`,`x`.`goals_against` AS `goals_against`,`x`.`goal_difference` AS `goal_difference`,`x`.`points` AS `points` from (select `st`.`season_id` AS `season_id`,`se`.`season_label` AS `season_label`,`t`.`team_id` AS `team_id`,`t`.`team_name` AS `team_name`,count(`r`.`match_id`) AS `played`,coalesce(sum(`r`.`wins`),0) AS `wins`,coalesce(sum(`r`.`draws`),0) AS `draws`,coalesce(sum(`r`.`losses`),0) AS `losses`,coalesce(sum(`r`.`goals_for`),0) AS `goals_for`,coalesce(sum(`r`.`goals_against`),0) AS `goals_against`,(cast(coalesce(sum(`r`.`goals_for`),0) as signed) - cast(coalesce(sum(`r`.`goals_against`),0) as signed)) AS `goal_difference`,coalesce(sum(((3 * `r`.`wins`) + `r`.`draws`)),0) AS `points` from (((`season_teams` `st` join `seasons` `se` on((`se`.`season_id` = `st`.`season_id`))) join `teams` `t` on((`t`.`team_id` = `st`.`team_id`))) left join (select `matches`.`match_id` AS `match_id`,`matches`.`season_id` AS `season_id`,`matches`.`home_team_id` AS `team_id`,`matches`.`home_score` AS `goals_for`,`matches`.`away_score` AS `goals_against`,(`matches`.`home_score` > `matches`.`away_score`) AS `wins`,(`matches`.`home_score` = `matches`.`away_score`) AS `draws`,(`matches`.`home_score` < `matches`.`away_score`) AS `losses` from `matches` where (`matches`.`match_status` = 'COMPLETED') union all select `matches`.`match_id` AS `match_id`,`matches`.`season_id` AS `season_id`,`matches`.`away_team_id` AS `team_id`,`matches`.`away_score` AS `goals_for`,`matches`.`home_score` AS `goals_against`,(`matches`.`away_score` > `matches`.`home_score`) AS `wins`,(`matches`.`away_score` = `matches`.`home_score`) AS `draws`,(`matches`.`away_score` < `matches`.`home_score`) AS `losses` from `matches` where (`matches`.`match_status` = 'COMPLETED')) `r` on(((`r`.`season_id` = `st`.`season_id`) and (`r`.`team_id` = `st`.`team_id`)))) group by `st`.`season_id`,`se`.`season_label`,`t`.`team_id`,`t`.`team_name`) `x`;

CREATE SQL SECURITY INVOKER VIEW `v_match_details` AS select `m`.`match_id` AS `match_id`,`c`.`competition_name` AS `competition_name`,`s`.`season_label` AS `season_label`,`m`.`kickoff_at` AS `kickoff_at`,`h`.`team_name` AS `home_team`,`a`.`team_name` AS `away_team`,`m`.`match_status` AS `match_status`,`m`.`home_score` AS `home_score`,`m`.`away_score` AS `away_score`,`m`.`is_synthetic` AS `is_synthetic` from ((((`matches` `m` join `seasons` `s` on((`s`.`season_id` = `m`.`season_id`))) join `competitions` `c` on((`c`.`competition_id` = `s`.`competition_id`))) join `teams` `h` on((`h`.`team_id` = `m`.`home_team_id`))) join `teams` `a` on((`a`.`team_id` = `m`.`away_team_id`)));

CREATE SQL SECURITY INVOKER VIEW `v_match_results` AS select `m`.`match_id` AS `match_id`,`m`.`kickoff_at` AS `kickoff_at`,`h`.`team_name` AS `home_team`,`a`.`team_name` AS `away_team`,`m`.`home_score` AS `home_score`,`m`.`away_score` AS `away_score`,(case when (`m`.`home_score` > `m`.`away_score`) then `h`.`team_name` when (`m`.`home_score` < `m`.`away_score`) then `a`.`team_name` else 'Draw' end) AS `result`,`m`.`is_synthetic` AS `is_synthetic` from ((`matches` `m` join `teams` `h` on((`h`.`team_id` = `m`.`home_team_id`))) join `teams` `a` on((`a`.`team_id` = `m`.`away_team_id`))) where (`m`.`match_status` = 'COMPLETED');

CREATE SQL SECURITY INVOKER VIEW `v_match_stat_coverage` AS select coalesce(`m`.`match_id`,`s`.`match_id`) AS `match_id`,`s`.`player_id` AS `player_id`,'MATCH_OR_BOTH' AS `coverage_side` from (`matches` `m` left join `player_match_stats` `s` on((`s`.`match_id` = `m`.`match_id`))) union all select coalesce(`m`.`match_id`,`s`.`match_id`) AS `match_id`,`s`.`player_id` AS `player_id`,'STAT_ONLY' AS `coverage_side` from (`player_match_stats` `s` left join `matches` `m` on((`m`.`match_id` = `s`.`match_id`))) where (`m`.`match_id` is null);

CREATE SQL SECURITY INVOKER VIEW `v_player_totals` AS select `p`.`player_id` AS `player_id`,`p`.`full_name` AS `full_name`,`t`.`team_name` AS `team_name`,`p`.`position` AS `position`,count(`s`.`match_id`) AS `recorded_appearances`,coalesce(sum(`s`.`minutes_played`),0) AS `recorded_minutes`,coalesce(sum(`s`.`goals`),0) AS `recorded_goals`,coalesce(sum(`s`.`assists`),0) AS `recorded_assists` from ((`players` `p` join `teams` `t` on((`t`.`team_id` = `p`.`team_id`))) left join `player_match_stats` `s` on((`s`.`player_id` = `p`.`player_id`))) group by `p`.`player_id`,`p`.`full_name`,`t`.`team_name`,`p`.`position`;

CREATE SQL SECURITY INVOKER VIEW `v_players_with_goals` AS select `p`.`player_id` AS `player_id`,`p`.`full_name` AS `full_name`,`t`.`team_name` AS `team_name` from (`players` `p` join `teams` `t` on((`t`.`team_id` = `p`.`team_id`))) where exists(select 1 from `player_match_stats` `s` where ((`s`.`player_id` = `p`.`player_id`) and (`s`.`goals` > 0)));

CREATE SQL SECURITY INVOKER VIEW `v_scheduled_fixtures` AS select `m`.`match_id` AS `match_id`,`m`.`kickoff_at` AS `kickoff_at`,`s`.`season_label` AS `season_label`,`h`.`team_name` AS `home_team`,`a`.`team_name` AS `away_team`,`m`.`is_synthetic` AS `is_synthetic` from (((`matches` `m` join `seasons` `s` on((`s`.`season_id` = `m`.`season_id`))) join `teams` `h` on((`h`.`team_id` = `m`.`home_team_id`))) join `teams` `a` on((`a`.`team_id` = `m`.`away_team_id`))) where (`m`.`match_status` = 'SCHEDULED');

CREATE SQL SECURITY INVOKER VIEW `v_team_home_away` AS select `t`.`team_id` AS `team_id`,`t`.`team_name` AS `team_name`,`r`.`venue` AS `venue`,count(0) AS `played`,sum(`r`.`goals_for`) AS `goals_for`,sum(`r`.`goals_against`) AS `goals_against`,sum((case when (`r`.`goals_for` > `r`.`goals_against`) then 3 when (`r`.`goals_for` = `r`.`goals_against`) then 1 else 0 end)) AS `points` from ((select `matches`.`home_team_id` AS `team_id`,'HOME' AS `venue`,`matches`.`home_score` AS `goals_for`,`matches`.`away_score` AS `goals_against` from `matches` where (`matches`.`match_status` = 'COMPLETED') union all select `matches`.`away_team_id` AS `team_id`,'AWAY' AS `venue`,`matches`.`away_score` AS `goals_for`,`matches`.`home_score` AS `goals_against` from `matches` where (`matches`.`match_status` = 'COMPLETED')) `r` join `teams` `t` on((`t`.`team_id` = `r`.`team_id`))) group by `t`.`team_id`,`t`.`team_name`,`r`.`venue`;

CREATE SQL SECURITY INVOKER VIEW `tl_season_teams` AS select `st`.`season_id` AS `season_id`,`st`.`team_id` AS `team_id` from ((`season_teams` `st` join `tl_seasons` `s` on((`st`.`season_id` = `s`.`season_id`))) join `teams` `t` on((`st`.`team_id` = `t`.`team_id`))) where (`t`.`team_name` in ('Arsenal','Chelsea','Liverpool','Manchester City','Manchester United','Tottenham Hotspur'));

CREATE SQL SECURITY INVOKER VIEW `tl_matches` AS select `m`.`match_id` AS `match_id`,`m`.`season_id` AS `season_id`,`m`.`home_team_id` AS `home_team_id`,`m`.`away_team_id` AS `away_team_id`,`m`.`kickoff_at` AS `kickoff_at`,`m`.`match_status` AS `match_status`,`m`.`home_score` AS `home_score`,`m`.`away_score` AS `away_score`,`m`.`is_synthetic` AS `is_synthetic` from (((`matches` `m` join `tl_seasons` `s` on((`m`.`season_id` = `s`.`season_id`))) join `tl_season_teams` `h` on(((`h`.`season_id` = `m`.`season_id`) and (`h`.`team_id` = `m`.`home_team_id`)))) join `tl_season_teams` `a` on(((`a`.`season_id` = `m`.`season_id`) and (`a`.`team_id` = `m`.`away_team_id`)))) where ((`m`.`is_synthetic` = 0) and exists(select 1 from `provider_matches` `p` where ((`p`.`match_id` = `m`.`match_id`) and (`p`.`provider` = 'api-football'))));

CREATE SQL SECURITY INVOKER VIEW `tl_player_match_stats` AS select `ps`.`match_id` AS `match_id`,`ps`.`player_id` AS `player_id`,`ps`.`minutes_played` AS `minutes_played`,`ps`.`goals` AS `goals`,`ps`.`assists` AS `assists`,0 AS `is_synthetic` from (`provider_player_stats` `ps` join `tl_matches` `m` on((`ps`.`match_id` = `m`.`match_id`))) where (`ps`.`minutes_played` > 0);

