_matches`.`home_score` AS `goals_against`,(`tl_matches`.`away_score` > `tl_matches`.`home_score`) AS `wins`,(`tl_matches`.`away_score` = `tl_matches`.`home_score`) AS `draws`,(`tl_matches`.`away_score` < `tl_matches`.`home_score`) AS `losses` from `tl_matches` where (`tl_matches`.`match_status` = 'COMPLETED')) `r` on(((`r`.`season_id` = `st`.`season_id`) and (`r`.`team_id` = `st`.`team_id`)))) group by `st`.`season_id`,`se`.`season_label`,`t`.`team_id`,`t`.`team_name`) `x`;

