CREATE SQL SECURITY INVOKER VIEW `tl_v_player_totals` AS select `p`.`player_id` AS `player_id`,`p`.`full_name` AS `full_name`,`t`.`team_name` AS `team_name`,`p`.`position` AS `position`,count(`s`.`match_id`) AS `recorded_appearances`,coalesce(sum(`s`.`minutes_played`),0) AS `recorded_minutes`,sum(`s`.`goals`) AS `recorded_goals`,sum(`s`.`assists`) AS `recorded_assists`,count(`s`.`goals`) AS `known_goal_appearances`,(count(`s`.`match_id`) - count(`s`.`goals`)) AS `unknown_goal_appearances`,count(`s`.`assists`) AS `known_assist_appearances`,(count(`s`.`match_id`) - count(`s`.`assists`)) AS `unknown_assist_appearances` from ((`tl_players` `p` join `teams` `t` on((`t`.`team_id` = `p`.`team_id`))) left join `tl_player_match_stats` `s` on((`s`.`player_id` = `p`.`player_id`))) group by `p`.`player_id`,`p`.`full_name`,`t`.`team_name`,`p`.`position`;

CREATE SQL SECURITY INVOKER VIEW `tl_v_players_with_goals` AS select `p`.`player_id` AS `player_id`,`p`.`full_name` AS `full_name`,`t`.`team_name` AS `team_name` from (`tl_players` `p` join `teams` `t` on((`t`.`team_id` = `p`.`team_id`))) where exists(select 1 from `tl_player_match_stats` `s` where ((`s`.`player_id` = `p`.`player_id`) and (`s`.`goals` > 0)));
